 * вибраної. Path — 1:1 з SVG-експорту MCP (`download_assets`), без ручного переписування.
 * Колір у SVG (#505050 / #003926) тут не використовується — задає tint у навбарі (ті самі значення).
 * Замінили попередні наближені контури (Everyday_Designs, node 2146:320), з яких частина була
 * добудована вручну.
 */
private fun vectorOf(name: String, svgPath: String): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f
    ).addPath(
        pathData = PathParser().parsePathString(svgPath).toNodes(),
        fill = SolidColor(Color.Black),
        pathFillType = PathFillType.NonZero
    ).build()

